type Cand { len: Int, seq: List[Int] }

fn none_cand() -> Cand {
  let empty: List[Int] = []
  return Cand { len: 0, seq: empty }
}

fn lex_less(a: List[Int], b: List[Int]) -> Bool {
  if a.is_empty() or b.is_empty() {
    return false
  }
  let x = a.first().unwrap_or(0)
  let y = b.first().unwrap_or(0)
  if x != y {
    return x < y
  }
  return lex_less(a: a.drop(1), b: b.drop(1))
}

fn better(a: Cand, b: Cand) -> Bool {
  if a.len != b.len {
    return a.len > b.len
  }
  return lex_less(a: a.seq, b: b.seq)
}

fn prefer(acc: Cand, c: Cand) -> Cand {
  if better(a: c, b: acc) {
    return c
  }
  return acc
}

fn consider(acc: Cand, c: Cand, x: Int) -> Cand {
  let tail_val = c.seq.last().unwrap_or(0)
  if tail_val < x {
    return prefer(acc: acc, c: c)
  }
  return acc
}

fn new_cand(cands: List[Cand], x: Int) -> Cand {
  let prev = cands.fold(none_cand(), fn(acc, c) => consider(acc: acc, c: c, x: x))
  if prev.len == 0 {
    return Cand { len: 1, seq: [x] }
  }
  return Cand { len: prev.len + 1, seq: prev.seq.push(x) }
}

pub fn lis(xs: List[Int]) -> List[Int] {
  let none: List[Cand] = []
  let cands = xs.fold(none, fn(cs, x) => cs.push(new_cand(cands: cs, x: x)))
  let best = cands.fold(none_cand(), fn(acc, c) => prefer(acc: acc, c: c))
  return best.seq
}
